fn exit_with_debug(code: i32, debug: bool){
    if debug {
        if code==0 {
            log_debug("Exit code 0 (SUCCESS)");
        } else {
            log_debug(&format!("Exit code {}", code));
        }
    }
    process::exit(code);
}

fn main(){
    let args: Vec<String> = env::args().skip(1).collect();
    // quick handle for empty: main help
    let mut p = Parsed::default();
    p.my_cnf_skip = false; // default my-cnf enabled, we track skip
    // Actually default is enabled, but we have bool for skip present
    // We'll parse

    // To handle help/version precedence we need to parse all
    // We'll iterate
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if arg == "--" {
            // rest positional
            i+=1;
            while i < args.len() {
                let a = &args[i];
                if p.cmd.is_none() {
                    // try command
                    if is_known_cmd(a) {
                        p.cmd = Some(Cmd::from(a));
                    } else {
                        // unknown command
                        log_error(&format!("Unknown command \"{}\"", a));
                        exit_with_debug(78, p.debug);
                    }
                } else {
                    p.positionals.push(a.clone());
                }
                i+=1;
            }
            break;
        } else if arg.starts_with("--") {
            // long
            let eq_pos = arg.find('=');
            let (name, val_opt) = if let Some(pos)=eq_pos {
                (&arg[2..pos], Some(arg[pos+1..].to_string()))
            } else {
                (&arg[2..], None)
            };
            // normalize name
            // handle skip- prefix is part of name, we keep as is for matching
            match name {
                "debug" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.debug = true;
                },
                "help" => {
                    // optional value
                    let mut hv: Option<String> = None;
                    let mut consumed_next = false;
                    if let Some(v) = val_opt {
                        if v.is_empty() {
                            hv = None;
                        } else {
                            hv = Some(v);
                        }
                    } else {
                        // look ahead
                        if i+1 < args.len() {
                            let next = &args[i+1];
                            if !next.starts_with("-") && is_known_cmd(next) {
                                hv = Some(next.clone());
                                consumed_next = true;
                            } else {
                                // if next is empty? Or not known, we don't consume as help value unless command already known?
                                // For cases like "--help" alone, no value
                                // For "--help" when command already set, we will set hv to command later
                            }
                        }
                    }
                    // If hv is None and cmd is Some and cmd != Help, set hv to cmd as_str
                    if hv.is_none() {
                        if let Some(ref c) = p.cmd {
                            if *c != Cmd::Help {
                                hv = Some(c.as_str().to_string());
                            }
                        }
                    }
                    p.help_opt = Some(hv);
                    if consumed_next {
                        i+=1;
                    }
                },
                "version" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.version_opt = true;
                },
                "my-cnf" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.my_cnf_deprecated = true;
                },
                "skip-my-cnf" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.my_cnf_skip = true;
                },
                "connect-options" => {
                    let val = if let Some(v)=val_opt { v } else {
                        if i+1 < args.len() && !args[i+1].starts_with("-") {
                            i+=1;
                            args[i].clone()
                        } else {
                            log_error(&format!("CLI: Missing required value for option {}", name));
                            exit_with_debug(78, p.debug);
                        }
                    };
                    p.connect_options = Some(val);
                },
                "host-wrapper" => {
                    let val = if let Some(v)=val_opt { v } else {
                        if i+1 < args.len() && !args[i+1].starts_with("-") {
                            i+=1;
                            args[i].clone()
                        } else {
                            log_error(&format!("CLI: Missing required value for option {}", name));
                            exit_with_debug(78, p.debug);
                        }
                    };
                    p.host_wrapper = Some(val);
                },
                "ignore-func" => {
                    let val = if let Some(v)=val_opt { v } else {
                        if i+1 < args.len() && !args[i+1].starts_with("-") {
                            i+=1;
                            args[i].clone()
                        } else {
                            log_error(&format!("CLI: Missing required value for option {}", name));
                            exit_with_debug(78, p.debug);
                        }
