                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.lint = Some(true);
                },
                "skip-lint" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.lint = Some(false);
                },
                "verify" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.verify = Some(true);
                },
                "skip-verify" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.verify = Some(false);
                },
                "write" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.write = Some(true);
                },
                "skip-write" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.write = Some(false);
                },
                "format" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.format_opt = Some(true);
                },
                "skip-format" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.format_opt = Some(false);
                },
                "new-schemas" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.new_schemas = Some(true);
                },
                "skip-new-schemas" => {
                    if val_opt.is_some() {
                        log_error(&format!("CLI: Unknown option \"{}\"", name));
                        exit_with_debug(78, p.debug);
                    }
                    p.new_schemas = Some(false);
                },
                _ => {
                    log_error(&format!("CLI: Unknown option \"{}\"", name));
                    exit_with_debug(78, p.debug);
                }
            }
        } else if arg.starts_with("-") && arg.len()>=2 {
            if arg.starts_with("-?") {
                let rem = &arg[2..];
                let hv = if rem.is_empty() { None } else {
                    let v = rem.trim_start_matches('=');
                    if v.is_empty() { None } else { Some(v.to_string()) }
                };
                let mut final_hv = hv;
                if final_hv.is_none() {
                    if let Some(ref c) = p.cmd {
                        if *c != Cmd::Help {
                            final_hv = Some(c.as_str().to_string());
                        }
                    } else {
                        if i+1 < args.len() && !args[i+1].starts_with("-") && is_known_cmd(&args[i+1]) {
                            final_hv = Some(args[i+1].clone());
                            i+=1;
                        }
                    }
                }
                p.help_opt = Some(final_hv);
            } else {
                let ch = arg.chars().nth(1).unwrap();
                let rest = &arg[2..];
                match ch {
                    'o' => {
                        let val = if !rest.is_empty() { rest.trim_start_matches('=').to_string() } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                i+=1; args[i].clone()
                            } else {
                                log_error(&format!("CLI: Missing required value for option {}", "connect-options"));
                                exit_with_debug(78, p.debug);
                            }
                        };
                        p.connect_options = Some(val);
                    },
                    'H' => {
                        let val = if !rest.is_empty() { rest.trim_start_matches('=').to_string() } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                i+=1; args[i].clone()
                            } else {
                                log_error(&format!("CLI: Missing required value for option {}", "host-wrapper"));
                                exit_with_debug(78, p.debug);
                            }
                        };
                        p.host_wrapper = Some(val);
                    },
                    'p' => {
                        if !rest.is_empty() {
                            let v = rest.trim_start_matches('=');
                            p.password = Some(v.to_string());
                            p.password_present = true;
                        } else {
                            p.password_prompt = true;
                            p.password_present = true;
                        }
                    },
                    'u' => {
                        let val = if !rest.is_empty() { rest.trim_start_matches('=').to_string() } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                i+=1; args[i].clone()
                            } else {
                                log_error(&format!("CLI: Missing required value for option {}", "user"));
                                exit_with_debug(78, p.debug);
                            }
                        };
                        p.user = Some(val);
                    },
                    'd' => {
                        let val = if !rest.is_empty() { rest.trim_start_matches('=').to_string() } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                i+=1; args[i].clone()
                            } else {
                                log_error(&format!("CLI: Missing required value for option {}", "dir"));
                                exit_with_debug(78, p.debug);
                            }
                        };
                        p.dir = Some(val);
                        p.dir_present = true;
                    },
                    'h' => {
                        let val = if !rest.is_empty() { rest.trim_start_matches('=').to_string() } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                i+=1; args[i].clone()
                            } else {
                                log_error(&format!("CLI: Missing required value for option {}", "host"));
                                exit_with_debug(78, p.debug);
                            }
                        };
                        p.host = Some(val);
                        p.host_present = true;
                        p.host_short = true;
                    },
                    'P' => {
                        let val = if !rest.is_empty() { rest.trim_start_matches('=').to_string() } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                i+=1; args[i].clone()
                            } else {
                                log_error(&format!("CLI: Missing required value for option {}", "port"));
                                exit_with_debug(78, p.debug);
                            }
                        };
                        p.port = Some(val);
                        p.port_present = true;
                    },
                    'S' => {
                        let val = if !rest.is_empty() { rest.trim_start_matches('=').to_string() } else {
                            if i+1 < args.len() {
                                if args[i+1].starts_with("-") {
                                    log_error(&format!("CLI: Missing required value for option {}", "socket"));
                                    exit_with_debug(78, p.debug);
                                }
                                i+=1; args[i].clone()
                            } else {
                                log_error(&format!("CLI: Missing required value for option {}", "socket"));
                                exit_with_debug(78, p.debug);
                            }
                        };
                        p.socket = Some(val);
                        p.socket_present = true;
                    },
                    'x' => {
                        let val = if !rest.is_empty() { rest.trim_start_matches('=').to_string() } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                i+=1; args[i].clone()
                            } else {
                                log_error(&format!("CLI: Missing required value for option {}", "alter-wrapper"));
                                exit_with_debug(78, p.debug);
                            }
                        };
                        p.alter_wrapper = Some(val);
                    },
                    'X' => {
                        let val = if !rest.is_empty() { rest.trim_start_matches('=').to_string() } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                i+=1; args[i].clone()
                            } else {
                                log_error(&format!("CLI: Missing required value for option {}", "ddl-wrapper"));
                                exit_with_debug(78, p.debug);
                            }
                        };
                        p.ddl_wrapper = Some(val);
                    },
                    'q' => {
                        if !rest.is_empty() {
                            log_error(&format!("CLI: Unknown option \"{}\"", rest));
                            exit_with_debug(78, p.debug);
                        }
                        p.brief = true;
                    },
                    'c' => {
                        let val = if !rest.is_empty() { rest.trim_start_matches('=').to_string() } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                i+=1; args[i].clone()
                            } else {
                                log_error(&format!("CLI: Missing required value for option {}", "concurrent-servers"));
                                exit_with_debug(78, p.debug);
                            }
                        };
                        p.concurrent_servers = Some(val);
                    },
                    '1' => {
                        if !rest.is_empty() {
                            log_error(&format!("CLI: Unknown option \"{}\"", rest));
                            exit_with_debug(78, p.debug);
                        }
                        p.first_only = true;
                    },
                    't' => {
                        let val = if !rest.is_empty() { rest.trim_start_matches('=').to_string() } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                i+=1; args[i].clone()
                            } else {
                                log_error(&format!("CLI: Missing required value for option {}", "temp-schema"));
                                exit_with_debug(78, p.debug);
                            }
                        };
                        p.temp_schema = Some(val);
                    },
                    'w' => {
                        let val = if !rest.is_empty() { rest.trim_start_matches('=').to_string() } else {
                            if i+1 < args.len() && !args[i+1].starts_with("-") {
                                i+=1; args[i].clone()
                            } else {
                                log_error(&format!("CLI: Missing required value for option {}", "workspace"));
                                exit_with_debug(78, p.debug);
                            }
                        };
                        p.workspace = Some(val);
                    },
                    _ => {
                        log_error(&format!("CLI: Unknown option \"{}\"", ch));
                        exit_with_debug(78, p.debug);
                    }
                }
            }
        } else {
            if p.cmd.is_none() {
                if is_known_cmd(arg) {
                    p.cmd = Some(Cmd::from(arg));
                } else {
                    log_error(&format!("Unknown command \"{}\"", arg));
                    exit_with_debug(78, p.debug);
                }
            } else {
                p.positionals.push(arg.clone());
            }
        }
        i+=1;
    }

    if p.password_prompt {
        use std::io::IsTerminal;
        if !std::io::stdin().is_terminal() {
            eprintln!("Enter password: ");
            log_error("STDIN must be a TTY to read password");
            log_error("Interactive password prompting requires an input terminal. To supply a password non-interactively, configure the password value in a global option file, or supply it directly on the command-line, or set the $MYSQL_PWD environment variable. For more information, see https://www.skeema.io/docs/options/#password");
            exit_with_debug(78, p.debug);
        }
    }

    if p.my_cnf_deprecated {
        log_warn("Option --my-cnf is deprecated. This option will be removed in Skeema v2, and .my.cnf will always be parsed, with additional safety logic already in place. For more information, visit https://www.skeema.io/v2-changes");
    }
    if p.temp_binlog_present {
        log_warn("Option --temp-schema-binlog is deprecated. This option will be removed in Skeema v2, with \"auto\" behavior always being used. For more information, visit https://www.skeema.io/v2-changes");
    }
    if p.temp_threads_present {
        log_warn("Option --temp-schema-threads is deprecated. This option will be removed in Skeema v2. Use the new temp-schema-mode enum option instead. See --help or visit https://www.skeema.io/docs/options/#temp-schema-mode");
    }
    if p.lint_display_width_present {
        log_warn("Option --lint-display-width is deprecated. This option will be removed in Skeema v2. For more information, visit https://www.skeema.io/v2-changes");
    }
    if p.alter_validate_virtual_present {
        log_warn("Option --alter-validate-virtual is deprecated. This option will be removed in Skeema v2. As an alternative, use alter-algorithm=copy, or configure alter-wrapper to use an external OSC tool.");
    }

    if let Some(Cmd::Help) = p.cmd {
        if p.positionals.len() > 1 {
            log_error(&format!("Extra command-line arg \"{}\" supplied; command help takes a max of 1 args", p.positionals[1]));
            exit_with_debug(78, p.debug);
        }
        if p.dir_present {
            log_error("CLI: Unknown option \"dir\"");
            exit_with_debug(78, p.debug);
        }
        if p.host_present {
            if p.host_long {
                log_error("The host option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options");
                exit_with_debug(78, p.debug);
            } else {
                log_error("CLI: Unknown option \"h\"");
                exit_with_debug(78, p.debug);
            }
        }
        if p.schema_present {
            log_error("The schema option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options");
            exit_with_debug(78, p.debug);
        }
        if let Some(ref cs) = p.concurrent_servers {
            match cs.parse::<i32>() {
                Ok(v) => {
                    if v < 1 {
                        log_error("concurrent-instances cannot be less than 1");
                        exit_with_debug(78, p.debug);
                    }
                },
                Err(_) => {
                    log_error(&format!("strconv.Atoi: parsing \"{}\": invalid syntax", cs));
                    exit_with_debug(78, p.debug);
                }
            }
        }
        if p.positionals.len() == 0 {
            if p.help_opt.is_some() {
                // help --help gives main help
                println!("{}", MAIN_HELP);
                exit_with_debug(0, p.debug);
            } else {
                println!("{}", MAIN_HELP);
                exit_with_debug(0, p.debug);
            }
        } else {
            let target = &p.positionals[0];
            if target == "version" {
                println!("{}", VERSION_STR);
                exit_with_debug(0, p.debug);
            } else if target == "help" {
                println!("{}", MAIN_HELP);
                exit_with_debug(0, p.debug);
            } else if is_known_cmd(target) {
                let txt = match target.as_str() {
                    "init" => INIT_HELP,
                    "add-environment" => ADD_ENV_HELP,
                    "diff" => DIFF_HELP,
                    "format" => FORMAT_HELP,
                    "lint" => LINT_HELP,
                    "pull" => PULL_HELP,
                    "push" => PUSH_HELP,
                    "version" => VERSION_HELP,
                    "help" => HELP_HELP,
                    _ => MAIN_HELP,
                };
                println!("{}", txt);
                exit_with_debug(0, p.debug);
            } else if target.is_empty() {
                log_error(&format!("Unknown command \"{}\"", target));
                exit_with_debug(2, p.debug);
            } else {
                log_error(&format!("Unknown command \"{}\"", target));
                exit_with_debug(2, p.debug);
            }
        }
    }

    if let Some(help_opt) = p.help_opt.clone() {
        // Check dir unknown before help
        if p.dir_present {
            // dir only allowed for init/add-env, but help target might be init/add-env? However help --dir=foo should be unknown per original (we saw help --dir=foo unknown). So check regardless.
            // If help target is init or add-environment, should dir be allowed? The original help --port=3306 gave help, not unknown, so port allowed. dir gave unknown even for help. So for help, dir is always unknown.
            log_error("CLI: Unknown option \"dir\"");
            exit_with_debug(78, p.debug);
        }
        // host/schema forbidden check for help option
        if p.host_present {
            // Determine effective cmd for check
            let effective_cmd = if let Some(Some(ref target)) = p.help_opt {
                if is_known_cmd(target) { Some(Cmd::from(target.as_str())) } else { p.cmd.clone() }
            } else {
                p.cmd.clone()
            };
            let allowed = match effective_cmd {
                Some(Cmd::Init) | Some(Cmd::AddEnv) => true,
                _ => false,
            };
            if !allowed {
                // need to distinguish long vs short for host
                if p.host_long {
                    log_error("The host option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options");
                    exit_with_debug(78, p.debug);
                } else if p.host_short {
                    log_error("CLI: Unknown option \"h\"");
                    exit_with_debug(78, p.debug);
                } else {
                    log_error("The host option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options");
                    exit_with_debug(78, p.debug);
                }
            }
        }
        if p.schema_present {
            let effective_cmd = if let Some(Some(ref target)) = p.help_opt {
                if is_known_cmd(target) { Some(Cmd::from(target.as_str())) } else { p.cmd.clone() }
            } else {
                p.cmd.clone()
            };
            let allowed = match effective_cmd {
                Some(Cmd::Init) => true,
                _ => false,
            };
            if !allowed {
                log_error("The schema option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options");
                exit_with_debug(78, p.debug);
            }
        }
        if let Some(ref cs) = p.concurrent_servers {
            match cs.parse::<i32>() {
                Ok(v) => {
                    if v < 1 {
                        log_error("concurrent-instances cannot be less than 1");
                        exit_with_debug(78, p.debug);
                    }
                },
                Err(_) => {
                    log_error(&format!("strconv.Atoi: parsing \"{}\": invalid syntax", cs));
                    exit_with_debug(78, p.debug);
                }
            }
        }
        if let Some(target_opt) = help_opt {
            if target_opt.is_none() {
                println!("{}", MAIN_HELP);
                exit_with_debug(0, p.debug);
            } else {
                let target = target_opt.unwrap();
                if target.is_empty() {
                    println!("{}", MAIN_HELP);
                    exit_with_debug(0, p.debug);
                } else if is_known_cmd(&target) {
                    let txt = match target.as_str() {
                        "init" => INIT_HELP,
                        "add-environment" => ADD_ENV_HELP,
                        "diff" => DIFF_HELP,
                        "format" => FORMAT_HELP,
                        "lint" => LINT_HELP,
                        "pull" => PULL_HELP,
                        "push" => PUSH_HELP,
                        "version" => VERSION_HELP,
                        "help" => HELP_HELP,
                        _ => MAIN_HELP,
                    };
                    println!("{}", txt);
                    exit_with_debug(0, p.debug);
                } else {
                    log_error(&format!("Unknown command \"{}\"", target));
                    exit_with_debug(2, p.debug);
                }
            }
        } else {
            println!("{}", MAIN_HELP);
            exit_with_debug(0, p.debug);
        }
    }

    if p.cmd.is_none() && !p.version_opt {
        println!("{}", MAIN_HELP);
        exit_with_debug(0, p.debug);
    }

    let is_version_cmd = matches!(p.cmd, Some(Cmd::Version));
    if p.version_opt || is_version_cmd {
        if is_version_cmd && p.positionals.len() > 0 {
            log_error(&format!("Extra command-line arg \"{}\" supplied; command version takes a max of 0 args", p.positionals[0]));
            exit_with_debug(78, p.debug);
        }
        if p.host_present {
            log_error("The host option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options");
            exit_with_debug(78, p.debug);
        }
        if p.schema_present {
            log_error("The schema option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options");
            exit_with_debug(78, p.debug);
        }
        if p.dir_present {
            log_error("CLI: Unknown option \"dir\"");
            exit_with_debug(78, p.debug);
        }
        if let Some(ref cs) = p.concurrent_servers {
            match cs.parse::<i32>() {
                Ok(v) => {
                    if v < 1 {
                        log_error("concurrent-instances cannot be less than 1");
                        exit_with_debug(78, p.debug);
                    }
                },
                Err(_) => {
                    log_error(&format!("strconv.Atoi: parsing \"{}\": invalid syntax", cs));
                    exit_with_debug(78, p.debug);
                }
            }
        }
        if let Some(ref sm) = p.ssl_mode {
            let valid = ["disabled","preferred","required",""];
            if !valid.contains(&sm.as_str()) {
                log_error(&format!("Invalid connection options: Option ssl-mode can only be set to one of these values: \"disabled\", \"preferred\", \"required\", \"\""));
                exit_with_debug(78, p.debug);
            }
        }
        if let Some(ref co) = p.connect_options {
            for token in co.split(',') {
                if token.is_empty() { continue; }
                if !token.contains('=') {
                    log_error(&format!("Invalid connection options: Option {} is missing a value at byte offset {} in connect-options \"{}\"", token, token.len(), co));
                    exit_with_debug(78, p.debug);
                }
            }
        }
        println!("{}", VERSION_STR);
        exit_with_debug(0, p.debug);
    }

    let cmd = p.cmd.clone().unwrap();

    if p.positionals.len() > cmd.max_args() {
        let extra = &p.positionals[cmd.max_args()];
        log_error(&format!("Extra command-line arg \"{}\" supplied; command {} takes a max of {} args", extra, cmd.as_str(), cmd.max_args()));
        exit_with_debug(78, p.debug);
    }
    if p.positionals.len() < cmd.min_args() {
        log_error(&format!("Too few positional args supplied on command line; command {} requires at least {} args", cmd.as_str(), cmd.min_args()));
        exit_with_debug(78, p.debug);
    }

    if p.dir_present {
        match cmd {
            Cmd::Init | Cmd::AddEnv => {},
            _ => {
                log_error("CLI: Unknown option \"dir\"");
                exit_with_debug(78, p.debug);
            }
        }
    }

    // host handling with long vs short distinction
    if p.host_present {
        match cmd {
            Cmd::Init | Cmd::AddEnv => {},
            _ => {
                if p.host_long {
                    log_error("The host option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options");
                    exit_with_debug(78, p.debug);
                } else {
                    log_error("CLI: Unknown option \"h\"");
                    exit_with_debug(78, p.debug);
                }
            }
        }
    }
    if p.schema_present {
        match cmd {
            Cmd::Init => {},
            _ => {
                log_error("The schema option cannot be set via command line for this command. For more information, visit https://www.skeema.io/docs/config/#limitations-on-host-and-schema-options");
                exit_with_debug(78, p.debug);
            }
        }
    }

    let mut allowed: HashSet<String> = HashSet::new();
    let globals = vec!["connect-options","debug","help","host-wrapper","ignore-func","ignore-proc","ignore-schema","ignore-table","my-cnf","skip-my-cnf","password","ssl-mode","user","version","port","socket"];
    for g in globals { allowed.insert(g.to_string()); }

    match cmd {
        Cmd::Init => {
            allowed.insert("dir".to_string());
            allowed.insert("host".to_string());
            allowed.insert("include-auto-inc".to_string());
            allowed.insert("schema".to_string());
            allowed.insert("strip-partitioning".to_string());
        },
        Cmd::AddEnv => {
            allowed.insert("dir".to_string());
            allowed.insert("host".to_string());
        },
        Cmd::Diff => {
            let list = vec![
                "alter-wrapper","alter-wrapper-min-size","ddl-wrapper",
