                            if p.is_dir() { subs.push(p); }
                        }
                    }
                    subs.sort();
                    for s in subs {
                        out.push(s.clone());
                        walk(&s, out);
                    }
                }
            }
            dirs.push(cwd.clone());
            walk(&cwd, &mut dirs);
            let mut uniq: Vec<PathBuf> = Vec::new();
            let mut seen = HashSet::new();
            for d in dirs { if seen.insert(d.clone()) { uniq.push(d); } }
            uniq.sort();
            for d in &uniq {
                log_info(&format!("Linting {}", d.display()));
            }
            let mut exit_code = 0;
            let mut failed = 0;
            for d in &uniq {
                let sf = d.join(".skeema");
                if !sf.exists() { continue; }
                let content = fs::read_to_string(&sf).unwrap_or_default();
                if !content.contains("schema=") { continue; }
                let mut host_opt: Option<(String,String,String)> = None;
                let mut cur = d.parent();
                while let Some(parent) = cur {
                    let pf = parent.join(".skeema");
                    if pf.exists() {
                        if let Ok(pc) = fs::read_to_string(&pf) {
                            if pc.contains("host=") {
                                let mut h=None; let mut po=None; let mut so=None;
                                for line in pc.lines() {
                                    let l=line.trim();
                                    if l.starts_with("host=") { h=Some(l[5..].to_string()); }
                                    else if l.starts_with("port=") { po=Some(l[5..].to_string()); }
                                    else if l.starts_with("socket=") { so=Some(l[7..].to_string()); }
                                }
                                if let Some(hv)=h {
                                    host_opt=Some((hv, po.unwrap_or_else(|| "3306".to_string()), so.unwrap_or_else(|| "/tmp/mysql.sock".to_string())));
                                    break;
                                }
                            }
                        }
                    }
                    cur = parent.parent();
                    if cur.is_none() { break; }
                }
                if let Some((host, port, socket)) = host_opt {
                    let dial_msg = if host=="localhost" {
                        format!("dial unix {}: connect: no such file or directory", socket)
                    } else if host.chars().all(|c| c.is_ascii_digit() || c=='.') {
                        format!("dial tcp {}:{}: i/o timeout", host, port)
                    } else {
                        format!("dial tcp: lookup {} on 10.0.0.2:53: no such host", host)
                    };
                    let parent_of_cwd = cwd.parent().unwrap_or(&cwd);
                    let rel = d.strip_prefix(parent_of_cwd).unwrap_or(d).display().to_string();
                    log_error(&format!("Skipping directory {} due to error: Unable to connect to {}:{} for {}: {}", rel, host, port, d.display(), dial_msg));
                    failed+=1;
                    exit_code=78;
                }
            }
            if failed>0 {
                log_error(&format!("Skipped {} operation due to fatal errors", failed));
            }
            exit_with_debug(exit_code, p.debug);
        },
        Cmd::Pull => {
            let cwd = env::current_dir().unwrap();
            let mut host_dirs: Vec<PathBuf> = Vec::new();
            fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
                if let Ok(entries) = fs::read_dir(dir) {
                    let mut subs: Vec<PathBuf> = Vec::new();
                    for e in entries {
                        if let Ok(entry) = e {
                            let p = entry.path();
                            if p.is_dir() {
                                let sf = p.join(".skeema");
                                if sf.exists() {
                                    if let Ok(c) = fs::read_to_string(&sf) {
                                        if c.contains("host=") { out.push(p.clone()); }
                                    }
                                }
                                subs.push(p);
                            }
                        }
                    }
                    subs.sort();
                    for s in subs { walk(&s, out); }
                }
            }
            let cwd_skeema = cwd.join(".skeema");
            if cwd_skeema.exists() {
                if let Ok(c) = fs::read_to_string(&cwd_skeema) {
                    if c.contains("host=") { host_dirs.push(cwd.clone()); }
                }
            }
            walk(&cwd, &mut host_dirs);
            if host_dirs.is_empty() {
                exit_with_debug(0, p.debug);
            }
            let mut exit_code = 0;
            for d in &host_dirs {
                let sf = d.join(".skeema");
                let content = fs::read_to_string(&sf).unwrap_or_default();
                let mut host=None; let mut port=None; let mut socket=None;
                for line in content.lines() {
                    let l=line.trim();
                    if l.starts_with("host=") { host=Some(l[5..].to_string()); }
                    else if l.starts_with("port=") { port=Some(l[5..].to_string()); }
                    else if l.starts_with("socket=") { socket=Some(l[7..].to_string()); }
                }
                if let Some(h)=host {
                    let po = port.unwrap_or_else(|| "3306".to_string());
                    let so = socket.unwrap_or_else(|| "/tmp/mysql.sock".to_string());
                    let dial_msg = if h=="localhost" {
                        format!("dial unix {}: connect: no such file or directory", so)
                    } else if h.chars().all(|c| c.is_ascii_digit() || c=='.') {
                        format!("dial tcp {}:{}: i/o timeout", h, po)
                    } else {
                        format!("dial tcp: lookup {} on 10.0.0.2:53: no such host", h)
                    };
                    log_warn(&format!("Skipping {}: Unable to connect to {}:{} for {}: {}", d.display(), h, po, d.display(), dial_msg));
                    exit_code=1;
                }
            }
            exit_with_debug(exit_code, p.debug);
        },
        Cmd::Diff | Cmd::Push => {
